// Terrain for the map's tile LOD (web design §7.3): the 61 tiles and the 12
// sites of a province, generated by the rules module (frontier.wasm
// `generate_province`) from its ring's seed, exactly as the program does.
// The module loads only when a tile-LOD frame first asks for terrain (web
// design §10: the wasm loads lazily; province LOD works without it); every
// answer is cached (LRU, 256 provinces, §11). A missing module or seed
// gives null, and the map stays at province detail for that province.
import { kernel as loadKernel, TERRAIN } from '../wasm.mjs';
import { FS } from '../fstate.mjs';
import { ringOf } from '../fgeo.mjs';

export const TERRAIN_CACHE = 256;
const hexBytes = h => Uint8Array.from(h.match(/../g), x => parseInt(x, 16));

/** The season record's seed of ring d (hex), or null (the ring is not open or not known yet). */
export const seasonSeed = ring => FS.record?.rings?.find?.(r => r.d === ring)?.seed ?? null;

/**
 * `terrainOf(p, q)` → `{terrain: [61 indices], sites: [tile index], names}`
 * or null while the module loads (then `onReady()` runs once) or when it
 * cannot answer. `load` returns the kernel; `seedOf(ring)` the ring seed.
 */
export function createTerrain({ load = loadKernel, seedOf = seasonSeed, onReady = () => {}, limit = TERRAIN_CACHE } = {}) {
  const cache = new Map();
  let k = null, failed = false, loading = false;
  const ensure = () => {
    if (k || failed || loading) return;
    loading = true;
    Promise.resolve().then(load).then(x => { k = x; loading = false; onReady(); }, () => { failed = true; loading = false; });
  };
  const terrainOf = (p, q) => {
    const key = `${p},${q}`;
    if (cache.has(key)) { const v = cache.get(key); cache.delete(key); cache.set(key, v); return v; }
    if (!k) { ensure(); return null; }
    const seed = seedOf(ringOf(p, q));
    if (!/^[0-9a-f]{64}$/i.test(seed ?? '')) return null;
    const r = k.call('generate_province', { ring_seed: hexBytes(seed), p, q });
    const t = r.ok ? r.value.terrain : null;
    const v = t ? { terrain: t.terrain, sites: t.sites.slice(0, t.siteCount), names: TERRAIN } : null;
    cache.set(key, v);
    if (cache.size > limit) cache.delete(cache.keys().next().value);
    return v;
  };
  terrainOf.status = () => (k ? 'ready' : failed ? 'unavailable' : 'loading');
  return terrainOf;
}
